<?php
require_once __DIR__ . '/item-editor-view.php';
function cssrRenderInventory(array $data, array $ui, array $actions, bool $preview = false, ?array $notice = null): void
{
    $ui['styles'][] = '../assets/css/inventory-list.css?v=' . filemtime(__DIR__ . '/../assets/css/inventory-list.css');
    $ui['scripts'][] = '../assets/js/inventory-list.js?v=' . filemtime(__DIR__ . '/../assets/js/inventory-list.js');
    if ($actions['can_manage']) {
        $ui['styles'][] = '../assets/css/item-editor.css?v=' . filemtime(__DIR__ . '/../assets/css/item-editor.css');
        $ui['scripts'][] = '../assets/js/item-editor.js?v=' . filemtime(__DIR__ . '/../assets/js/item-editor.js');
    }
    cssrUiStart($ui);
    $filters = $data['filters']; $route = $actions['list'];
    $statusClasses = ['AVAILABLE'=>'success','LOW STOCK'=>'warning','OUT OF STOCK'=>'danger','INVALID'=>'invalid'];
    $hasFilters = (bool)array_filter(array_intersect_key($filters,array_flip(['q','classification','stock_status','procurement_type','storage_location'])));
?>
<div class="cu-stack" data-inventory>
    <div class="cu-page-heading cu-inventory-heading"><div><p class="cu-eyebrow">CSSR Inventory Management</p><h1>Inventory</h1><p class="cu-lead cu-muted">Find items, review stock levels, and keep supplies ready for care.</p></div>
    <?php if ($actions['can_manage']): ?><button type="button" class="cu-btn" data-item-editor="new"><?=cssrUiIcon('plus')?> Add Item</button><?php endif; ?></div>
    <?php if ($preview): ?><div class="cu-alert"><?=cssrUiIcon('box')?><div><strong>Inventory design preview</strong>Sample records only. Filters and pagination work; item forms demonstrate the design without saving. <a href="../pages/items.php">Open live inventory</a>.</div></div><?php endif; ?>
    <?php if ($notice && $notice['type'] === 'success'): ?><script type="application/json" id="inventory-success-notice"><?=json_encode($notice['message'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><?php elseif ($notice): ?><div class="cu-alert" role="status"><?=cssrUiEscape($notice['message'])?></div><?php endif; ?>
    <section class="cu-card" aria-label="Search and filter inventory"><form class="cu-card-body cu-stack" action="<?=cssrUiEscape($route)?>" method="get" id="inventory-filters">
        <div class="cu-inventory-search"><div class="cu-inventory-search-field"><?=cssrUiIcon('search')?><label class="cu-sr" for="inventory-search">Search item name, item code, or classification</label><input class="cu-input" type="search" id="inventory-search" name="q" placeholder="Search item name, item code, or classification" value="<?=cssrUiEscape($filters['q'])?>"></div><button type="submit" class="cu-btn"><?=cssrUiIcon('search')?> Search</button></div>
        <div class="cu-inventory-filter-grid"><?php foreach (['classification'=>'Classification','stock_status'=>'Stock Status','procurement_type'=>'Procurement Type','storage_location'=>'Storage Location'] as $key=>$label): ?><div class="cu-field"><label for="filter-<?=$key?>"><?=$label?></label><select class="cu-input" id="filter-<?=$key?>" name="<?=$key?>"><option value="">All <?=strtolower($label === 'Classification' ? 'classifications' : ($label === 'Stock Status' ? 'statuses' : ($label === 'Procurement Type' ? 'procurement types' : 'locations')))?></option><?php if ($filters[$key] !== '' && !in_array($filters[$key],$data['options'][$key],true)): ?><option value="<?=cssrUiEscape($filters[$key])?>" selected><?=cssrUiEscape($filters[$key])?> (no matches)</option><?php endif; ?><?php foreach ($data['options'][$key] as $option): ?><option value="<?=cssrUiEscape($option)?>" <?=$filters[$key] === $option ? 'selected' : ''?>><?=cssrUiEscape($option)?></option><?php endforeach; ?></select></div><?php endforeach; ?></div>
        <input type="hidden" name="per_page" value="<?=(int)$filters['per_page']?>">
        <div class="cu-inventory-filter-note"><span><?= $filters['storage_location'] !== '' ? 'Stock balances are for ' . cssrUiEscape($filters['storage_location']) . ' only.' : 'Stock balances are totals across all storage locations.' ?></span><div class="cu-actions"><a class="cu-btn cu-btn-ghost cu-btn-sm" href="<?=cssrUiEscape($route)?>">Reset filters</a><button type="submit" class="cu-btn cu-btn-secondary cu-btn-sm">Apply filters</button></div></div>
    </form></section>
    <section class="cu-inventory-summary" aria-label="Summary of matching inventory items">
    <?php foreach (['total'=>'Total Items','available'=>'Available','low'=>'Low Stock','out'=>'Out of Stock'] as $key=>$label): ?><div><span><?=$label?></span><strong class="cu-summary-<?=$key?>" data-inventory-summary="<?=$key?>"><?=number_format($data['summary'][$key])?></strong></div><?php endforeach; ?>
    </section>
    <section class="cu-card" aria-labelledby="inventory-list-heading"><div class="cu-card-head"><div><h2 id="inventory-list-heading">Inventory items</h2><p><?=$hasFilters ? 'Matching' : 'Active'?> inventory records · Select a row to view item details.</p></div><?php if ($data['summary']['invalid']): ?><span class="cu-badge cu-badge-invalid"><?=number_format($data['summary']['invalid'])?> invalid <?= $data['summary']['invalid'] === 1 ? 'record' : 'records'?></span><?php endif; ?></div>
        <div class="cu-table-wrap" tabindex="0" role="region" aria-label="Inventory list; scroll horizontally for all item actions"><table class="cu-table cu-inventory-table"><caption class="cu-sr">Inventory items matching the selected filters. Press Enter on a row to open its details.</caption><thead><tr><th scope="col">Item Code</th><th scope="col">Item Name</th><th scope="col">Classification</th><th scope="col">Unit</th><th scope="col" class="cu-number">Current Stock</th><th scope="col" class="cu-number">Reorder Level</th><th scope="col">Status</th><th scope="col">Action</th></tr></thead><tbody>
        <?php foreach ($data['rows'] as $item): $id = (int)$item['id']; ?>
        <tr data-inventory-row data-item-id="<?=$id?>" tabindex="0" aria-label="View <?=cssrUiEscape($item['item_name'] ?: $item['item_code'])?> details">
            <td class="cu-item-code"><?=cssrUiEscape($item['item_code'] ?: 'Missing code')?></td><td><strong class="cu-item-name"><?=cssrUiEscape($item['item_name'] ?: 'Unnamed item')?></strong></td><td class="cu-classification"><?=cssrUiEscape($item['classification'] ?: 'Not specified')?></td><td><?=cssrUiEscape($item['unit'] ?: '—')?></td><td class="cu-number cu-stock-value"><?=number_format((int)$item['current_stock'])?></td><td class="cu-number"><?=number_format((int)$item['minimum_stock'])?></td><td><span class="cu-badge cu-badge-<?=$statusClasses[$item['stock_status']]?>"><?=cssrUiEscape($item['stock_status'])?></span></td>
            <td><div class="cu-row-actions"><?php foreach (['view'=>'View','edit'=>'Edit','history'=>'Stock History'] as $action=>$label): ?><?php if ($action === 'edit' && !$actions['can_manage']) continue; ?>
                <?php if ($action === 'edit'): ?><button type="button" class="cu-btn cu-btn-ghost cu-btn-sm" data-item-editor="edit" data-item-id="<?=$id?>" aria-label="Edit: <?=cssrUiEscape($item['item_name'] ?: $item['item_code'])?>">Edit</button><?php continue; endif; ?>
                <?php if ($preview): ?><button type="button" class="cu-btn cu-btn-ghost cu-btn-sm" data-preview-item="<?=$id?>" data-preview-action="<?=$action?>" <?=$action === 'view' ? 'data-inventory-view' : ''?> aria-label="<?=$label?>: <?=cssrUiEscape($item['item_name'] ?: $item['item_code'])?>"><?=$label?></button><?php else: ?><a class="cu-btn cu-btn-ghost cu-btn-sm" href="<?=cssrUiEscape($actions[$action] . $id . ($action === 'history' ? '#stock-history' : ''))?>" <?=$action === 'view' ? 'data-inventory-view' : ''?> aria-label="<?=$label?>: <?=cssrUiEscape($item['item_name'] ?: $item['item_code'])?>"><?=$label?></a><?php endif; ?>
            <?php endforeach; ?></div></td>
        </tr><?php endforeach; ?>
        <?php if (!$data['rows']): ?><tr><td colspan="8"><div class="cu-empty"><span class="cu-icon-tile"><?=cssrUiIcon('search')?></span><h3><?=$hasFilters ? 'No matching items' : 'No inventory items yet'?></h3><p><?=$hasFilters ? 'Try another search or reset the filters to see all active items.' : 'Add your first item to begin building the inventory.'?></p><?php if ($hasFilters): ?><a class="cu-btn cu-btn-secondary" href="<?=cssrUiEscape($route)?>">Reset filters</a><?php endif; ?></div></td></tr><?php endif; ?>
        </tbody></table></div>
        <div class="cu-table-foot cu-inventory-footer"><span role="status">Showing <?=number_format($data['first'])?>–<?=number_format($data['last'])?> of <?=number_format($data['summary']['total'])?> items</span>
            <form class="cu-inventory-pagesize" method="get" action="<?=cssrUiEscape($route)?>"><?php foreach ($filters as $key=>$value): if (in_array($key,['page','per_page'],true) || $value === '') continue; ?><input type="hidden" name="<?=cssrUiEscape($key)?>" value="<?=cssrUiEscape($value)?>"><?php endforeach; ?><label for="inventory-per-page">Rows</label><select class="cu-input" id="inventory-per-page" name="per_page" data-inventory-page-size><?php foreach ([10,25,50] as $size): ?><option value="<?=$size?>" <?=$size === $filters['per_page'] ? 'selected' : ''?>><?=$size?></option><?php endforeach; ?></select><noscript><button class="cu-btn cu-btn-secondary cu-btn-sm">Apply</button></noscript></form>
            <nav class="cu-inventory-pagination" aria-label="Inventory pagination">
                <?php if ($filters['page'] > 1): ?><a class="cu-page-link" href="<?=cssrUiEscape(cssrInventoryUrl($route,$filters,['page'=>$filters['page']-1]))?>" rel="prev">Previous</a><?php else: ?><span class="cu-page-link" aria-disabled="true">Previous</span><?php endif; ?>
                <?php $pageNumbers = array_values(array_unique(array_merge([1], range(max(1,$filters['page']-1),min($data['pages'],$filters['page']+1)),[$data['pages']]))); sort($pageNumbers); $lastPage = 0; foreach ($pageNumbers as $number): ?><?php if ($lastPage && $number > $lastPage+1): ?><span aria-hidden="true">…</span><?php endif; ?><a class="cu-page-link" href="<?=cssrUiEscape(cssrInventoryUrl($route,$filters,['page'=>$number]))?>" aria-label="Page <?=$number?>" <?=$number === $filters['page'] ? 'aria-current="page"' : ''?>><?=$number?></a><?php $lastPage=$number; endforeach; ?>
                <?php if ($filters['page'] < $data['pages']): ?><a class="cu-page-link" href="<?=cssrUiEscape(cssrInventoryUrl($route,$filters,['page'=>$filters['page']+1]))?>" rel="next">Next</a><?php else: ?><span class="cu-page-link" aria-disabled="true">Next</span><?php endif; ?>
            </nav>
        </div>
    </section>
    <p class="cu-inventory-note">INVALID identifies incomplete item details or negative stock/reorder values. These records are included in Total Items and shown separately from stock availability counts.</p>
</div>
<?php if ($actions['can_manage']) cssrRenderItemEditor($data['rows'],$actions,$preview); ?>
<?php if ($preview): ?>
<dialog class="cu-dialog" id="inventory-preview-dialog" aria-labelledby="inventory-preview-title"><div class="cu-dialog-head"><h2 id="inventory-preview-title">Item Details</h2><button type="button" class="cu-icon-button" data-cu-dismiss aria-label="Close item preview"><?=cssrUiIcon('close')?></button></div><div class="cu-card-body cu-stack"><div><h3 data-preview-item-name></h3><p class="cu-muted" data-preview-item-code></p></div><dl class="cu-inventory-detail-list"><div><dt>Classification</dt><dd data-preview-classification></dd></div><div><dt>Current Stock</dt><dd data-preview-stock></dd></div><div><dt>Unit</dt><dd data-preview-unit></dd></div></dl><div data-preview-history hidden><div class="cu-alert"><div><strong>Sample stock record</strong>Opening balance: <span data-history-balance></span> units. This is synthetic data, not a hospital transaction.</div></div></div><p class="cu-inventory-note">Design preview only. The live page opens the existing authorized item workflow.</p></div><div class="cu-dialog-foot"><button class="cu-btn cu-btn-secondary" type="button" data-cu-dismiss>Close</button></div></dialog>
<script type="application/json" id="inventory-preview-data"><?=json_encode($data['rows'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR)?></script>
<?php endif; cssrUiEnd(); }
